quotes.text:
    }
  }
}

if (!urlSpec) return NS_ERROR_OUT_OF_MEMORY;

if ((options->format_out == nsMimeOutput::nsMimeMessageBodyDisplay) &&
    (PL_strncasecmp(aMessageURL, urlSpec, strlen(urlSpec)) == 0)) {
  PR_FREEIF(urlSpec);
  return NS_OK;
}

nsCOMPtr<nsIURI> uri;
nsresult rv = NS_NewURI(getter_AddRefs(uri), urlSpec);
PR_FREEIF(urlSpec);
